# Multiple versions and multiple editions might be installed, so we iterate over versions installed.
# If version preference is given, we filter only matching versions, otherwise the highest version is picked.
mvs_versions = []
for p in mvs_paths:
    if not p.is_dir():
        continue
    for v in p.iterdir():
        if not v.is_dir():
            continue
        if version_preference is not None and v.name != version_preference:
            continue
        # The version should have editions inside
        if any(e.name in edition_preferences for e in v.iterdir()):
            mvs_versions.append(v)

mvs_versions.sort(key=lambda p: p.name, reverse=True)

